body.script:
  (()=>{
    'use strict';
    const games=JSON.parse(document.getElementById('catalogData').textContent);
    const grid=document.getElementById('gameGrid'),search=document.getElementById('search'),count=document.getElementById('resultCount'),title=document.getElementById('sectionTitle'),desktop=document.getElementById('desktopCategories'),mobile=document.getElementById('mobileCategories'),toast=document.getElementById('toast');
    const state={category:'All',query:''};let toastTimer;
    const escapeHtml=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&','<':'<','>':'>',"'":''','"':'"'}[char]));
    const filtered=()=>games.filter(game=>(state.category==='All'||game.category===state.category)&&(!state.query||game.name.toLowerCase().includes(state.query)||game.category.toLowerCase().includes(state.query)));
    function showToast(message){toast.textContent=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),3500)}
    function categoryMarkup(){const values=['All',...new Set(games.map(game=>game.category))];return values.map(value=>{const total=value==='All'?games.length:games.filter(game=>game.category===value).length;return ''+escapeHtml(value)+''+total+''}).join('')}
    function drawCategories(){const markup=categoryMarkup();desktop.innerHTML=markup;mobile.innerHTML=markup}
    const displayName=name=>name.replace(/Lacey's Flash Games/gi,"Lacey's Flash Collection").replace(/Carnival Games DS/gi,'Carnival DS').replace(/game made by isreal-gpt/gi,'Made by Israel-GPT').replace(/Game & Watch Collection/gi,'Watch Collection').replace(/games?/gi,'Title').trim();
    function render(){const list=filtered();count.textContent=list.length+' title'+(list.length===1?'':'s');title.textContent=state.category==='All'?'All titles':state.category;grid.innerHTML=list.length?list.map(game=>{const name=displayName(game.name);return '
'+escapeHtml(name)+''+escapeHtml(game.category)+'↗'}).join(''):'

No titles found.Try a different search or category.'}
    function decodeHtml(encoded){const binary=atob(encoded),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);return new TextDecoder('utf-8').decode(bytes)}
    function prepareGameHtml(encoded){let html=decodeHtml(encoded);html=html.replace(/]*\bsrc=["'](?:https?:)?\/\/www\.google\.com\/jsapi[^"']*["'][^>]*>\s*<\/script>/gi,'').replace(/window\.parent\.maeExportApis_\s*\(\s*\)\s*;?/g,'');if(!/<base\b/i.test(html)){const base='';html=/
]*>/i.test(html)?html.replace(/
]*>/i,match=>match+base):base+html}return html}
    function hostedGameWrapper(game){const name=escapeHtml(displayName(game.name)),url=escapeHtml(game.url);return '
'+name+'
Opening '+name+'...'}
    function openGame(game){try{const opened=window.open('about:blank','_blank');if(!opened){showToast('Allow pop-ups for this page, then try again.');return}opened.document.open('text/html','replace');opened.document.write(game.url?hostedGameWrapper(game):prepareGameHtml(game.html));opened.document.close();try{opened.opener=null}catch{}}catch(error){showToast('This title could not be opened.')}}
    function chooseCategory(event){const button=event.target.closest('[data-category]');if(!button)return;state.category=button.dataset.category;drawCategories();render();window.scrollTo({top:0,behavior:'smooth'})}
    desktop.addEventListener('click',chooseCategory);mobile.addEventListener('click',chooseCategory);
    grid.addEventListener('click',event=>{const card=event.target.closest('[data-game]');if(!card)return;event.preventDefault();const game=games.find(item=>item.id===card.dataset.game);if(game)openGame(game)});
    document.getElementById('randomGame').addEventListener('click',()=>openGame(games[Math.floor(Math.random()*games.length)]));
    search.addEventListener('input',()=>{state.query=search.value.trim().toLowerCase();render()});
    document.addEventListener('keydown',event=>{if(event.key==='/'&&document.activeElement!==search){event.preventDefault();search.focus()}});
    drawCategories();render();
  })();
